const __pageData = JSON.parse('{"title":"Week 06 — Bytes to instructions: starting an 8086 decoder in C","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"materials/week-06/PLAN.md","filePath":"materials/week-06/PLAN.md"}');
